--
-- Name: get_auth(text); Type: FUNCTION; Schema: pgbouncer; Owner: supabase_admin
--

CREATE FUNCTION pgbouncer.get_auth(p_usename text) RETURNS TABLE(username text, password text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  BEGIN
      RAISE DEBUG 'PgBouncer auth request: %', p_usename;

      RETURN QUERY
      SELECT
          rolname::text,
          CASE WHEN rolvaliduntil < now()
              THEN null
              ELSE rolpassword::text
          END
      FROM pg_authid
      WHERE rolname=$1 and rolcanlogin;
  END;
  $_$;


ALTER FUNCTION pgbouncer.get_auth(p_usename text) OWNER TO supabase_admin;

--
-- Name: enforce_single_trip_vote(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enforce_single_trip_vote() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_trip_id uuid;
  v_type text;
  v_existing_id uuid;
begin
  select trip_id, type into v_trip_id, v_type
  from public.trip_poll_options
  where id = new.option_id;

  if v_trip_id is null then
    raise exception 'Poll option does not exist';
  end if;

  -- Remove any previous vote the user cast on another option of the
  -- SAME type (section) within the same trip
  select v.id into v_existing_id
  from public.trip_poll_votes v
  join public.trip_poll_options o on o.id = v.option_id
  where v.user_id = new.user_id
    and o.trip_id = v_trip_id
    and o.type = v_type
    and v.option_id <> new.option_id
  limit 1;

  if v_existing_id is not null then
    delete from public.trip_poll_votes where id = v_existing_id;
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.enforce_single_trip_vote() OWNER TO postgres;

--
-- Name: finalize_expired_trip_polls(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finalize_expired_trip_polls() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  r record;
  v_winner uuid;
  v_winner_title text;
  v_member record;
begin
  for r in
    select id, title, voting_deadline
    from public.trips
    where planning_stage = 'DESTINATION_VOTING'
      and voting_deadline is not null
      and voting_deadline < now()
  loop
    -- Place-poll winner (most votes, earliest proposal wins ties)
    select o.id, o.title into v_winner, v_winner_title
    from public.trip_poll_options o
    left join public.trip_poll_votes v on v.option_id = o.id
    where o.trip_id = r.id and o.type = 'place'
    group by o.id, o.title, o.created_at
    order by count(v.id) desc, o.created_at asc
    limit 1;

    update public.trips
    set destination = coalesce(v_winner_title, 'Voting in Progress'),
        planning_stage = 'ITINERARY_BUILDING',
        updated_at = now()
    where id = r.id;

    -- Notify every accepted member (host included)
    for v_member in
      select user_id
      from public.trip_participants
      where trip_id = r.id and status = 'accepted'
    loop
      values (
        v_member.user_id,
        (select host_id from public.trips where id = r.id),
        'poll_result',
        'Poll Results Are In!',
        case
          when v_winner is not null
            then format('The destination poll for "%s" has ended — "%s" won!', r.title, v_winner_title)
          else format('The destination poll for "%s" has ended with no clear winner.', r.title)
        end,
        false
      );
    end loop;

    v_winner := null;
    v_winner_title := null;
  end loop;
end;
$$;


ALTER FUNCTION public.finalize_expired_trip_polls() OWNER TO postgres;

--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  VALUES (
    NEW.id,
    NEW.raw_user_meta_data->>'first_name',
    NEW.raw_user_meta_data->>'last_name',
    NEW.raw_user_meta_data->>'username',
    NEW.email
  );
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.handle_new_user() OWNER TO postgres;

--
-- Name: is_trip_host(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.is_trip_host(trip_uuid uuid) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.trips
    where id = trip_uuid
      and host_id = auth.uid()
  );
$$;


ALTER FUNCTION public.is_trip_host(trip_uuid uuid) OWNER TO postgres;

--
-- Name: is_trip_member(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.is_trip_member(trip_uuid uuid) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
