CREATE POLICY "Profiles update policy" ON public.profiles FOR UPDATE USING ((auth.uid() = id)) WITH CHECK ((auth.uid() = id));


--
-- Name: expense_settlement_items Trip members can view settlement items; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Trip members can view settlement items" ON public.expense_settlement_items FOR SELECT USING ((auth.uid() IN ( SELECT tp.user_id
   FROM (public.trip_participants tp
     JOIN public.expense_settlements es ON ((es.trip_id = tp.trip_id)))
  WHERE (es.id = expense_settlement_items.settlement_id))));


--
-- Name: expense_settlements Trip members can view settlements; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Trip members can view settlements" ON public.expense_settlements FOR SELECT USING ((auth.uid() IN ( SELECT trip_participants.user_id
   FROM public.trip_participants
  WHERE (trip_participants.trip_id = expense_settlements.trip_id))));


--
-- Name: trip_itinerary_reactions Users can delete their own itinerary reaction; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Users can delete their own itinerary reaction" ON public.trip_itinerary_reactions FOR DELETE USING ((auth.uid() = user_id));


--
-- Name: trip_stay_comments Users can delete their own stay comment; Type: POLICY; Schema: public; Owner: postgres
--

