--
-- Name: trip_participants Users can join or host can add members; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Users can join or host can add members" ON public.trip_participants FOR INSERT WITH CHECK (((user_id = auth.uid()) OR (EXISTS ( SELECT 1
   FROM public.trips
  WHERE ((trips.id = trip_participants.trip_id) AND (trips.host_id = auth.uid()))))));


--
-- Name: trip_participants Users can leave or host can kick members; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Users can leave or host can kick members" ON public.trip_participants FOR DELETE USING (((user_id = auth.uid()) OR (EXISTS ( SELECT 1
   FROM public.trips
  WHERE ((trips.id = trip_participants.trip_id) AND (trips.host_id = auth.uid()))))));


