-- Name: push_tokens Users can manage their own push token; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Users can manage their own push token" ON public.push_tokens USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));


